INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('anterior-deltoid', 'Anterior Deltoid', 'shoulder_girdle', 'The anterior deltoid is the front portion of the three-part deltoid muscle that caps the shoulder. It runs from the outer end of the collarbone down to a point on the side of the upper arm bone (the deltoid tuberosity). Sitting right over the front of the shoulder joint, it is easy to see and feel as the rounded muscle at the front of the shoulder. It works closely with the chest muscles during pushing tasks and is often heavily developed by pressing and front-raise style training, which can leave it dominant over the smaller muscles at the back of the shoulder.', 'The anterior deltoid raises the arm forward and overhead (flexion) and assists in turning the upper arm inward and drawing it across the body. It is a major contributor to pressing and reaching-forward actions and partners with the chest during push-ups and overhead presses.', 'Commonly short and overactive in people whose training or daily work is heavy on forward pressing and reaching. When it dominates, it helps hold the upper arm rolled forward, adding to a rounded-shoulder look. It is rarely judged weak in screening; the usual pattern is that it overworks relative to the back-of-shoulder and mid-back muscles. A client with a markedly forward-set shoulder may benefit from professional evaluation.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('deep-abdominals', 'Abdominal Wall (Rectus + Transversus)', 'trunk', 'The deep abdominals group together the rectus abdominis, the long strap running vertically down the front of the belly from the lower ribs and sternum to the pubic bone, and the transversus abdominis, the deepest abdominal layer whose fibers wrap horizontally around the trunk like a corset. The rectus is the visible "six-pack" muscle that bends the trunk forward, while the transversus sits underneath the obliques and attaches into the broad sheet around the spine. Together they form the front and deep walls of the abdomen, spanning from the ribcage to the pelvis, and they work as the main flexors and bracing support for the front of the trunk.', 'The rectus abdominis flexes the trunk forward, curling the ribcage toward the pelvis and helping tilt the pelvis to flatten the low-back arch. The transversus abdominis compresses the abdomen and draws tight the deep trunk sheet, bracing the spine before and during movement. Together the abdominal wall controls the position of the ribcage over the pelvis and resists the trunk tipping backward.', 'Commonly under-supporting in clients whose ribcage flares upward, whose low back stays arched, or whose belly is carried forward. When the deep abdominals are lengthened and slow to engage, the back extensors dominate and the trunk drifts into extension. In screening, difficulty drawing the ribs down and bracing the deep abdominal wall points to under-activity here rather than tightness.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('deep-cervical-flexors', 'Deep Cervical Flexors', 'head_neck', 'The deep cervical flexors are a group of small muscles, including the longus colli and longus capitis, that lie deep at the front of the neck directly against the cervical spine. They run vertically along the front of the neck vertebrae, with the upper portion reaching the base of the skull. Sitting beneath the windpipe and the larger surface muscles, they cannot be seen or easily felt, but they act like a deep corset for the neck, holding the cervical curve and supporting the head from the inside. They are the deep stabilizers meant to do the quiet, continuous work of keeping the head balanced over the spine.', 'The deep cervical flexors gently nod the head forward at the top of the neck and support the natural cervical curve from the inside. Rather than producing large movements, their main job is endurance-style stabilizing: holding the head balanced over the spine and counterbalancing the muscles at the back of the neck throughout the day.', 'Commonly under-active and weak, especially when the larger surface muscles such as the SCM take over head support. When these deep stabilizers fade, the head tends to drift forward and the chin pokes out, since little is holding the cervical curve from the inside. In screening they are far more often flagged as weak than tight; endurance and the ability to gently nod and hold are the usual concern.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('deep-hip-external-rotators', 'Deep Hip External Rotators (Piriformis Group)', 'hip_pelvis', 'The deep hip external rotators are a group of six short muscles tucked beneath the gluteus maximus at the back of the hip — the piriformis, the two gemelli, the two obturators and quadratus femoris. They run roughly horizontally from the sacrum and the sitting-bone region across to the back of the greater trochanter at the top of the thigh bone. Short and close to the joint, they act like a deep cuff around the back of the hip, much as the rotator cuff wraps the shoulder. The piriformis is the most familiar of the group and sits at the deepest layer of the posterior hip.', 'The deep hip external rotators turn the thigh outward (external rotation) and, with the hip bent, help draw it out to the side. Their main value is control rather than power: they center the ball of the hip in its socket and steady the joint through standing and walking. Acting from the leg, they also influence how the pelvis rotates over the planted foot.', 'Commonly short and overactive on one side, especially with cross-legged sitting or one-sided loading, where they can hold the thigh turned out and contribute to a pelvis that is rotated to one side. In screening, asymmetric hip rotation range or a pelvis that sits turned toward one side points to shortened rotators that may benefit from release.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('gastrocnemius-soleus', 'Gastrocnemius & Soleus', 'knee_leg', 'The gastrocnemius and soleus form the calf at the back of the lower leg and share the Achilles tendon into the heel. The gastrocnemius is the larger, two-headed muscle that crosses both the knee and the ankle, starting just above the back of the knee on the thigh bone. The soleus lies underneath it and crosses only the ankle, beginning lower down on the back of the shin. Together they point the foot downward, and because the gastrocnemius spans the knee it also assists with knee bending. As a unit the calf pair is central to standing balance and to push-off in walking, running, and rising onto the toes.', 'The calf pair plantarflexes the ankle — pointing the foot and pushing the body forward in every step and rise onto the toes — while the gastrocnemius also assists in bending the knee. Just as importantly, the soleus works almost continuously during quiet standing as a postural muscle, making tiny adjustments that keep the body from toppling forward over the feet.', 'The calf commonly reads as short and overactive in clients who stand with weight shifted forward or who keep the knees locked back, since it works overtime to balance the body over the feet. Tightness here can pull the knee and ankle into less optimal positions. It may benefit from professional evaluation when ankle mobility is limited or the heels lift early during a squat.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('gluteus-maximus', 'Gluteus Maximus', 'hip_pelvis', 'The gluteus maximus is the largest and most superficial muscle of the buttock, forming most of its visible bulk. It arises from a broad area across the back of the pelvis — the back of the ilium, the edge of the sacrum and the tailbone — and its fibers run down and outward to attach onto the IT band on the side of the thigh and onto the femur itself. Its fibers are coarse and powerful, built for force rather than fine control. Sitting at the very back of the hip, it is the main engine for driving the thigh backward and for standing up against gravity from a bent-hip position.', 'The gluteus maximus is the primary hip extender, driving the thigh backward in standing, climbing, sprinting and rising from a squat. Its outer fibers also turn the thigh outward and, through the IT band, help steady the knee. Working from the leg, it pulls the back of the pelvis down to control forward tilt and keeps the trunk upright over the hips.', 'Commonly under-active and slow to fire in people who sit a great deal, where short hip flexors on the front of the hip reciprocally quiet the glutes. As the largest hip extender, a sleepy gluteus maximus lets the pelvis tip or shift forward and shifts work onto the low back and hamstrings. In screening it often shows as difficulty driving the hips fully back to neutral and a tendency to over-arch the low back instead.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('gluteus-medius', 'Gluteus Medius', 'hip_pelvis', 'The gluteus medius is a fan-shaped muscle on the outer surface of the pelvis, lying partly under the gluteus maximus. It arises from the broad outer face of the ilium and narrows into a short tendon that attaches to the bony point at the top of the thigh bone (the greater trochanter). Its front and back fibers pull in slightly different directions, which lets it both lift the leg out to the side and fine-tune hip rotation. Positioned right over the side of the hip, it is the key frontal-plane stabilizer that keeps the pelvis level when you stand on one leg.', 'The gluteus medius lifts the thigh out to the side (hip abduction) and, just as importantly, works in reverse: when you stand on one leg it holds the opposite side of the pelvis from dropping. Its forward and rear fibers also help rotate the hip. This makes it the main muscle keeping the pelvis level through every step of walking and running.', 'Commonly weak or poorly timed, which lets the pelvis drop or sway to one side during single-leg loading such as walking, stairs or running. An under-performing gluteus medius is closely tied to the knee falling inward and to side-to-side pelvic unleveling. It can also become short and overactive on the lower side when the pelvis is habitually tilted. Screening often reveals a pelvis that tips toward the unsupported side during a single-leg stance.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('hamstrings', 'Hamstrings', 'knee_leg', 'The hamstrings are three muscles on the back of the thigh — the biceps femoris on the outer side and the semitendinosus and semimembranosus on the inner side. They begin on the sitting bone (ischial tuberosity) of the pelvis, run down the back of the thigh, and cross both the hip and the knee before attaching below the knee on the shin. Because they span two joints, they both extend the hip and bend the knee. That dual role makes them important stabilizers linking the pelvis to the lower leg, and it means their length and strength affect posture from the hips all the way down to the knee.', 'The hamstrings bend the knee and extend the hip, powering walking, running, and standing up from a chair. Working with the glutes, they pull the pelvis out of a forward-tipped position and help hold the trunk upright over the legs. At the knee they also decelerate the lower leg as it swings and resist the joint snapping into full extension.', 'In screening, the hamstrings frequently read as underactive when the glutes are dominant or when the pelvis sways forward, leaving the back of the thigh unable to anchor the pelvis or control the knee. They may benefit from professional evaluation when a client cannot hinge at the hip without the lower back taking over. Both length and strength are worth checking, since a short-but-weak hamstring is common.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('hip-adductors', 'Hip Adductors', 'hip_pelvis', 'The hip adductors are a group of muscles on the inner thigh — chiefly adductor longus, adductor brevis, adductor magnus, gracilis and pectineus. As a group they run from the lower front of the pelvis (the pubic bone and sitting bone) down the inner thigh to attach along the length of the femur, with gracilis crossing all the way to the inner shin. Their bulk forms the inner-thigh mass you can feel when you squeeze the knees together. Because they span the inner hip, their length and tone affect how the pelvis sits side-to-side as well as how the thigh draws toward and across the midline.', 'The hip adductors draw the thigh inward toward the midline and across the body, and they help control the outward swing of the leg during walking and side-stepping. They also contribute to hip flexion and to steadying the pelvis over the standing leg. In single-leg loading they work alongside the outer-hip muscles to manage how the thigh tracks over the foot.', 'Commonly short and overactive on one side in people who sit cross-legged or stand with weight loaded asymmetrically, where the inner thigh stays shortened. Tightness here can draw the pelvis down on one side and pull the knee toward the midline. In screening, restricted side-to-side hip opening or a knee that drifts inward under load points toward shortened adductors that may benefit from length work.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('iliopsoas', 'Iliopsoas (Hip Flexors)', 'hip_pelvis', 'The iliopsoas is the deepest and most powerful hip flexor, made of two muscles that share a common tendon: the psoas major, which runs from the front of the lumbar spine, and the iliacus, which lines the inner bowl of the pelvis. The two blend together, cross the front of the hip joint, and attach to a small bump on the inner thigh bone (the lesser trochanter). Because the psoas links the spine directly to the leg, it sits deep in the abdomen behind the gut and cannot be felt from the surface. Its line of pull spans both the lumbar spine and the hip, so its length and tone influence pelvic tilt and low-back position as much as hip motion itself.', 'The iliopsoas lifts the thigh toward the chest (hip flexion) and helps drive the knee upward in walking, running, and stair climbing. Working from the leg, it can tilt the pelvis forward and add to the lumbar curve. It also acts as a deep stabilizer of the lumbar spine and hip, steadying the trunk when you sit up from lying down.', 'Commonly short and overactive in people who sit for long stretches, since the hip stays bent for hours and the muscle adapts to that shortened length. Tightness here tends to pull the pelvis into a forward tilt or shift and can leave the deep abdominals and glutes feeling under-used. In screening it usually shows up as a hip that resists full extension when standing tall or stepping the leg back.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('latissimus-dorsi', 'Latissimus Dorsi', 'trunk', 'The latissimus dorsi is a large, fan-shaped muscle covering much of the lower and mid-back. It arises from a broad sheet over the lower thoracic and lumbar spine, the back of the pelvis, and the lower ribs, then narrows as its fibers sweep upward and wrap toward the front of the upper arm bone. Because it bridges the pelvis, spine, ribcage, and arm, it links shoulder movement to the trunk. It can be felt as the muscle forming the back wall of the armpit. Its wide attachments mean that tension in the lat can pull on the spine and ribcage, not only the arm.', 'The latissimus dorsi pulls the arm down and back and rotates it inward, powering movements like pulling, rowing, and pushing up out of a chair. Working from the arm end, it can also lift and tilt the ribcage and extend the spine. Through its broad spinal attachment it assists trunk extension and side-bending, linking forceful arm action to the low back and pelvis.', 'Commonly short in clients who do heavy pulling work or sit with rounded, reaching postures, where the lat shortens between the arm and the spine. Tightness here can limit overhead reach and tug the ribcage into extension. In screening, restricted overhead arm raising with the low back arching to compensate is a typical sign that lat length, rather than weakness, is the concern.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('levator-scapulae', 'Levator Scapulae', 'head_neck', 'The levator scapulae is a strap-like muscle running along the side and back of the neck. It begins on the bony side projections of the top four neck vertebrae and travels downward to attach at the upper inner corner of the shoulder blade. For much of its length it sits underneath the upper trapezius, so it is hard to feel directly, though its lower attachment at the inner corner of the shoulder blade is a common site of muscular tension. As its name suggests, it is built to lift the shoulder blade, and it also has a strong influence on the side of the neck.', 'The levator scapulae lifts the shoulder blade and tips its lower edge inward, and it helps side-bend and rotate the neck toward the same side. When the shoulder blade is anchored, it assists in supporting and steadying the neck. It works alongside the upper trapezius to raise and stabilize the shoulder during everyday carrying and reaching.', 'Commonly short and overactive, especially in people who hold the head forward, hike one shoulder, or carry one-sided loads. Because it bridges the neck and the shoulder blade, elevated resting tone here often shows up as restricted range at the upper inner corner of the shoulder blade and along the side of the neck. In screening it is far more often flagged as tight than weak; resting length and tone are the typical concern.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('lower-trapezius', 'Lower Trapezius', 'head_neck', 'The lower trapezius is the bottom section of the large, diamond-shaped trapezius muscle. Its fibers begin on the spinous processes of the lower and mid back vertebrae and angle upward and outward to attach near the inner end of the bony ridge on the shoulder blade. This places it across the lower part of the area between and just below the shoulder blades. Because its fibers pull downward and inward, it draws the shoulder blade down toward the spine, and it is a key partner to the upper trapezius in rotating the shoulder blade smoothly when the arm lifts overhead.', 'The lower trapezius pulls the shoulder blade down and in toward the spine and helps rotate it upward as the arm raises overhead. Paired with the upper trapezius, it forms a force couple that turns the shoulder blade smoothly during arm elevation, and it helps anchor the blade down so the shoulder does not hike up during reaching and lifting.', 'Commonly lengthened and under-active. When it fails to anchor the shoulder blade down, the upper trapezius and levator scapulae take over, and the shoulders tend to ride up and round forward. This under-use shows up across forward-head, rounded-shoulder, and hiked-shoulder patterns alike. In screening it is far more often flagged as weak than tight; the ability to draw the shoulder blade down and hold it is the usual concern.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('lumbar-erector-spinae', 'Lumbar Erector Spinae', 'trunk', 'The lumbar erector spinae are the lower portion of the erector spinae columns, running vertically through the low back on either side of the lumbar spine. They arise from the broad thoracolumbar sheet and the back of the pelvis and sacrum, then travel upward to attach along the lumbar vertebrae and lower ribs as part of the iliocostalis and longissimus tracts. They form the thick muscular ridges that can be felt either side of the spine just above the waistband. As powerful postural muscles, they stay active to support the natural inward curve of the low back and to keep the trunk from collapsing forward.', 'The lumbar erector spinae extend the low back, deepening the lumbar curve and lifting the trunk upright from a bent position. They also help the trunk side-bend toward the working side. A large part of their job is steady postural control: holding the spine erect during standing and sitting, and slowing the descent when bending forward by lengthening under load.', 'Commonly short and overactive in clients who stand in a swayed posture or carry load in front of the body, where the low back stays arched to keep the chest up. Held in this shortened position, these muscles can feel tight and ropey beside the lumbar spine. In screening they tend to read as overactive paired with under-supporting deep abdominals, so length here is the usual focus.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('middle-trapezius', 'Middle Trapezius', 'head_neck', 'The middle trapezius is the central band of the large, diamond-shaped trapezius muscle, with fibers running roughly horizontally between the spine and the shoulder blade. It attaches along the spinous processes of the upper back vertebrae and travels outward to the bony ridge along the top of the shoulder blade. It sits in the area between the shoulder blades that many people think of as the upper back. Because its fibers pull straight inward, it is the muscle most directly responsible for drawing the shoulder blades back toward the spine and holding them there against the forward pull of the chest.', 'The middle trapezius draws the shoulder blade inward toward the spine (retraction) and helps anchor it firmly against the rib cage, giving the arm a stable base to move from. It works with the rhomboids and lower trapezius to keep the shoulder blades set back and steady during reaching, pulling, and carrying.', 'Commonly lengthened and under-active in people whose shoulders round forward, since the chest muscles shorten and the mid-back is held in a stretched, switched-off position. When it fails to hold the shoulder blades back, the upper trapezius tends to take over and the rounded look persists. In screening it is far more often flagged as weak than tight; the ability to draw the shoulder blades back and hold them is the usual concern.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('obliques', 'Internal & External Obliques', 'trunk', 'The internal and external obliques are the angled abdominal muscles that form the sides of the waist, layered between the ribs and the pelvis. The external oblique is the outer layer, with fibers running downward and forward; the internal oblique lies just beneath it with fibers running the opposite way. Together they wrap the trunk like crossed straps, attaching to the lower ribs, the broad abdominal sheet at the midline, and the rim of the pelvis. This crisscross arrangement makes them well suited to twisting and side-bending the trunk and to controlling rotation between the ribcage and pelvis during everyday movement.', 'The obliques bend the trunk sideways and rotate it, with each external oblique teaming up with the opposite internal oblique to turn the ribcage and pelvis relative to one another. They also compress the abdomen and help set the position of the ribcage over the pelvis. Working together on both sides, they assist trunk flexion and provide rotational stability during walking, lifting, and one-sided tasks.', 'In rotational asymmetry the obliques often work unevenly: shortened and overactive on one side, lengthened and underactive on the other. Clients with one-sided habits such as always crossing the same leg or loading one side in sport tend to show this pattern. In screening, the focus is the left-to-right balance of oblique tone and control, since a side difference rather than overall weakness usually drives a rotated trunk or pelvis.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('pectoralis-major', 'Pectoralis Major', 'shoulder_girdle', 'The pectoralis major is the large, fan-shaped muscle that forms the bulk of the chest. It has two heads: an upper (clavicular) head running from the collarbone and a lower (sternocostal) head running from the breastbone and the cartilage of the upper ribs. Both heads converge and twist together to attach onto the front of the upper arm bone (humerus), just below the shoulder. Because its fibers cross the front of the shoulder joint, anything it does pulls the arm forward and inward across the body. It is a powerful, surface-level muscle that is easy to see and feel, and it tends to be heavily developed by pushing-style training.', 'The pectoralis major brings the arm forward and across the chest (flexion and horizontal adduction) and rotates the upper arm inward. It is the prime mover in pushing actions such as a bench press, push-up, or shoving a door open. Working with other chest and shoulder muscles, it also helps draw the whole shoulder forward and down.', 'Commonly short and overactive in people who do a lot of pressing work or sit hunched over a desk for long stretches. When it is tight, it pulls the upper arm into the rounded, inwardly rotated position seen with forward-set shoulders, and it can feel firm or restricted when the arm is opened out to the side. It is rarely flagged as weak in a screening setting; length and resting tone are the usual focus, and a client may benefit from professional evaluation if range feels notably limited.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('pectoralis-minor', 'Pectoralis Minor', 'shoulder_girdle', 'The pectoralis minor is a small, flat, triangular muscle that lies hidden underneath the larger pectoralis major. It runs from the front of the third, fourth, and fifth ribs upward and outward to a small bony hook on the shoulder blade called the coracoid process. Unlike the pectoralis major, it attaches to the shoulder blade rather than the arm, so its pull acts on how the shoulder blade sits against the ribcage. Because it is deep and cannot be seen at the surface, its influence on posture is easy to overlook even though it has a strong say in shoulder-blade position.', 'The pectoralis minor draws the shoulder blade forward and down around the ribcage and tips its top edge forward (anterior tilt). It also helps pull the shoulder blade down when the arm is fixed, such as when pushing up out of a chair. In short, it anchors and positions the shoulder blade rather than moving the arm directly.', 'Commonly shortened by long hours of seated, hunched work and heavy pushing exercise. When it shortens, it tips the shoulder blade forward and rounds the shoulder toward the chest, which can crowd the space at the front of the shoulder. It is seldom seen as weak in screening; the usual concern is that it stays clamped down and short. A client whose shoulder blade sits noticeably tilted forward may benefit from professional evaluation.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('popliteus', 'Popliteus', 'knee_leg', 'The popliteus is a small, flat, triangular muscle deep behind the knee. It runs from the outer edge of the thigh bone (lateral femoral condyle) diagonally down and inward to the back of the shinbone (tibia), sitting beneath the larger calf muscles where it cannot be seen or felt from the surface. Despite its size it has an outsized role at the very start of knee bending. It is sometimes called the "key" of the knee because of the way it frees the joint from a fully straightened, locked position so that flexion can begin. It also adds quiet support to the back and inner corner of the knee during bent-knee positions.', 'The popliteus unlocks the knee: when the leg is fully straight it rotates the shinbone slightly to release the joint so that bending can start. It also helps stabilize the back and inner side of the knee, supporting the structures there during bent-knee stances and guarding the joint against drifting backward into hyperextension.', 'Because it initiates unlocking of the knee, the popliteus commonly reads as underactive in clients whose knees rest in a hyperextended, locked-back position — the joint never asks the muscle to do its job. It may benefit from professional evaluation when a knee habitually sits in full extension rather than a soft stance. It is rarely the muscle that screens as short.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('quadratus-lumborum', 'Quadratus Lumborum', 'trunk', 'The quadratus lumborum is a deep, roughly square muscle on each side of the low back, sitting between the rim of the pelvis and the lowest rib. It runs from the back of the iliac crest upward to the twelfth rib and the sides of the lumbar vertebrae, filling the space between the pelvis and ribcage at the back of the waist. It lies deep to the erector spinae and behind the abdominal contents, so it cannot be seen from the surface. Because it bridges the pelvis, lumbar spine, and lowest rib, it has a strong influence on side-to-side leveling of the pelvis and on stabilizing the low back.', 'The quadratus lumborum side-bends the trunk toward its own side and, working from above, hikes the pelvis upward on that side. Acting from the pelvis it helps extend and stabilize the lumbar spine and anchors the lowest rib during breathing. Working together on both sides, the pair steady the low back and resist sideways collapse of the trunk during standing and single-leg tasks.', 'Commonly short and overactive on one side in clients who sit with a hip hiked, carry loads on one side, or stand with weight shifted onto one leg. A shortened quadratus lumborum lifts the pelvis on that side and side-bends the trunk, so it often reads as a left-to-right tone difference rather than overall weakness. In screening, the side that holds the hip higher is the usual focus.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('quadriceps', 'Quadriceps (incl. VMO)', 'knee_leg', 'The quadriceps are a group of four muscles on the front of the thigh — three vastus muscles (lateralis, medialis, intermedius) and the rectus femoris on top. They join into a common tendon that wraps the kneecap (patella) and attaches onto the top of the shinbone, so together they straighten the knee. The rectus femoris also crosses the hip and helps lift the thigh. The vastus medialis oblique (VMO), the teardrop of muscle just above and inside the kneecap, is singled out here because it steers how the patella tracks and tends to fade first when the inner thigh is underused. As a group the quadriceps span from the pelvis and upper thigh bone down across the knee.', 'The quadriceps extend (straighten) the knee in every push-off, squat, stair climb, and stand-up, while the rectus femoris head also helps flex the hip. Beyond producing motion they act as a brake, controlling the speed of knee bending as you sit down or step downstairs, and the VMO steadies the kneecap so it glides cleanly through its groove.', 'The quadriceps often read as short and overactive in clients who lock the knees backward or stand with weight shifted onto the front of the thigh. They can also test underactive on the inner-knee VMO side when alignment drifts. Screening looks at both the resting knee position and how the kneecap tracks; this group may benefit from professional evaluation when one knee consistently hyperextends or the kneecap drifts off-center.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('rectus-femoris', 'Rectus Femoris', 'hip_pelvis', 'The rectus femoris is the only one of the four quadriceps muscles that crosses both the hip and the knee. It runs straight down the middle of the front thigh, beginning on the front of the pelvis at the bony point just below and in front of the hip (the anterior inferior iliac spine) and joining the shared quadriceps tendon that wraps the kneecap and attaches to the top of the shinbone. Because it spans two joints, it both lifts the thigh at the hip and straightens the knee, and its length is shared between those movements — bending the knee while the hip is extended puts it on full stretch. This two-joint arrangement makes the rectus femoris a direct mechanical link between the tilt of the pelvis and the front of the thigh.', 'The rectus femoris flexes the hip, drawing the thigh up toward the trunk, and extends the knee, contributing to kicking, stair climbing, and the forward swing of the leg in walking. Because it anchors onto the front of the pelvis, a short rectus femoris can add to a forward pelvic tilt as one of several hip flexors, deepening the low-back arch. It shares hip-flexion duty with the iliopsoas and knee-extension duty with the three deeper quadriceps heads, sitting at the crossover of the two.', 'The rectus femoris commonly reads as short and overactive in clients who sit for long stretches or who stand with the pelvis tipped forward, since its hip attachment keeps it loaded in those positions. When shortened it can add to a forward pelvic tilt as part of the hip-flexor group, working alongside the iliopsoas rather than on its own. It may benefit from professional evaluation when the front of the hip feels persistently tight or the lower back stays arched; a kneeling or standing thigh stretch that combines hip extension with knee bending lengthens it directly.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('rhomboids', 'Rhomboids', 'shoulder_girdle', 'The rhomboids are a pair of flat, diamond-shaped muscles in the upper back that run from the spine out to the inner edge of the shoulder blade. There are two: the rhomboid minor up near the base of the neck and the larger rhomboid major just below it. Their fibers angle downward and outward from the spine to the shoulder blade, so when they pull, they draw the shoulder blade in toward the spine and slightly upward. They sit beneath the trapezius and work as the main anchors holding the shoulder blades back against the ribcage.', 'The rhomboids pull the shoulder blades in toward the spine (retraction) and help tip the lower edge of the blade inward (downward rotation). They steady the shoulder blade against the ribcage so the arm has a stable base to work from, and they resist the forward drift of the shoulders during reaching and pulling tasks.', 'Commonly lengthened and underactive in people who sit hunched or train the front of the body far more than the back. When they cannot hold the shoulder blades back, the shoulders drift forward and the upper back rounds. In screening they are usually flagged as weak rather than short, and a client who struggles to draw the shoulder blades together may benefit from professional evaluation and targeted strengthening.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('serratus-anterior', 'Serratus Anterior', 'shoulder_girdle', 'The serratus anterior is a broad, fan-shaped muscle that wraps along the side of the ribcage. Its finger-like slips arise from the upper eight or nine ribs and run backward and around to attach along the inner edge of the shoulder blade, on the surface facing the ribs. Because it sits between the shoulder blade and the ribcage, it acts like a strap that holds the shoulder blade flat against the chest wall. The lower part also helps swing the shoulder blade upward, which makes it essential for raising the arm overhead. Its serrated, saw-tooth origins give the muscle its name.', 'The serratus anterior holds the shoulder blade flat and snug against the ribcage and rotates it upward so the arm can reach overhead. It also draws the shoulder blade forward around the ribcage (protraction), as in a punching or pushing motion, and provides the stable base the arm needs during pressing and reaching.', 'Commonly underactive and poorly coordinated in people with rounded shoulders and limited overhead reach. When it does not engage well, the inner edge of the shoulder blade can lift away from the ribcage (winging) and upward rotation suffers, leaving the shoulder poorly positioned. In screening it is usually flagged as weak; a client with visible winging or difficulty stabilizing the shoulder blade may benefit from professional evaluation.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('sternocleidomastoid', 'Sternocleidomastoid', 'head_neck', 'The sternocleidomastoid, often shortened to SCM, is the prominent rope-like muscle you can see on the front and side of the neck when you turn your head to one side. It has two lower attachments, one on the top of the breastbone and one on the inner end of the collarbone, and these join to attach behind the ear on the bony bump of the skull. There is one on each side of the neck. Because it runs from the front of the chest up to the back of the skull, it has a strong influence on how the head and neck are carried, and it is easy to see and feel at the surface.', 'Working on one side, the sternocleidomastoid turns the head to the opposite side and tips it toward the same shoulder. Working together, the two sides bend the neck forward, and when the head is fixed they can assist breathing by lifting the upper ribs. They also help control and steady the head during everyday movement.', 'Commonly short and overactive in people who hold the head forward or jut the chin, since the upper portion stays engaged to keep the face level while the lower neck bends forward. Over-reliance on the SCM often pairs with under-use of the deeper neck flexors. In screening it is far more often flagged as tight than weak, and one side may carry more tension than the other; resting length and tone are the usual concern.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('suboccipitals', 'Suboccipitals', 'head_neck', 'The suboccipitals are four small paired muscles tucked deep at the very top of the neck, running between the upper two cervical vertebrae (C1 and C2) and the base of the skull. They are short, dense muscles packed with position-sensing nerve endings, which makes them important players in head positioning and balance, not just movement. Because they sit underneath the larger neck muscles, they cannot be seen or easily felt from the surface, but they work constantly whenever the head tips, nods, or rotates a few degrees.', 'The suboccipitals fine-tune head position: they extend the head on the upper neck (tipping the face upward), assist small rotations, and continuously adjust the skull against gravity. They also feed the nervous system rich positional information that coordinates eye and neck movement.', 'Commonly short and overactive in people who hold a forward head position — desk workers, frequent phone users, and anyone whose chin pokes forward. When the head sits in front of the shoulders, these muscles stay contracted to keep the eyes level. They are rarely weak in screening contexts; length and tone are the usual concern.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('tfl-it-band', 'TFL & IT Band', 'hip_pelvis', 'The tensor fasciae latae (TFL) is a small muscle at the front-outer edge of the hip that blends into the iliotibial (IT) band, a long sheet of dense connective tissue running down the outside of the thigh to just below the knee. The TFL arises from the front of the iliac crest and, within a few inches, hands its pull off to the IT band, which continues down to attach below the knee on the outer shin. Together they act as one functional unit along the side of the leg. Because the band crosses both the hip and the knee, tension in the TFL is transmitted all the way down to the outer knee.', 'The TFL flexes, abducts and inwardly rotates the hip, and through the IT band it helps stabilize the pelvis and the outer knee during standing and walking. The band itself stores and returns tension as the leg loads, steadying side-to-side motion. Working as a unit, the TFL and IT band manage how the thigh tracks over the foot and how the outer knee is supported.', 'Commonly short and overactive, especially when the nearby gluteus medius is under-performing and the TFL takes over its side-stabilizing job. A tight TFL and IT band can pull the kneecap and outer knee outward and add to side-of-thigh tension. In screening, restricted inward hip motion or outer-knee tightness under load points to a shortened TFL-IT band unit that may benefit from release and length work.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('thoracic-erector-spinae', 'Thoracic Erector Spinae', 'trunk', 'The thoracic erector spinae are the mid-back portion of the long erector spinae columns that run vertically on either side of the spine. In the thoracic region they span from the lower ribs and thoracolumbar area up toward the upper ribs and the transverse processes of the vertebrae, layered as the iliocostalis and longissimus tracts. They sit just beside the spinous processes, deep to the trapezius and rhomboids, and can be felt as the firm ridges either side of the backbone. Because they are postural muscles, they stay lightly active through the day to hold the trunk upright against gravity, working across the mid-back where the ribcage attaches.', 'The thoracic erector spinae extend the mid-back, straightening the trunk and resisting the forward pull of gravity when sitting or standing. Acting on one side, they help the trunk side-bend and rotate. They also work to control the speed of bending forward, paying out length as the chest lowers and reversing it to bring the trunk back upright.', 'Commonly short and overactive in clients who sit with the chest pressed up and the upper back arched, or who habitually lean the trunk backward. When the mid-back is held in extension, these muscles stay contracted and can feel like tight bands beside the spine. In screening they more often read as overactive rather than lengthened, so length and tone are the usual focus.', NULL, NULL)
INSERT INTO muscles (slug, name, region, anatomy_summary, function_text, screening_notes, reviewed_by, reviewed_at) VALUES ('upper-trapezius', 'Upper Trapezius', 'head_neck', 'The upper trapezius is the top section of the large, diamond-shaped trapezius muscle that spans the back of the neck and upper back. Its upper fibers run from the base of the skull and the back of the neck down and outward to the collarbone and the tip of the shoulder. This is the visible slope you can see and feel between the neck and the point of the shoulder. Because it attaches to both the head and the shoulder-blade region, it ties neck position and shoulder position together, and it tends to carry a lot of everyday tension from holding the head up, shrugging, and steadying loads carried in the hands or on the shoulders.', 'The upper trapezius lifts the shoulder blade (the shrugging motion), helps turn it upward when the arm reaches overhead, and assists in extending and side-bending the neck. Paired with the lower trapezius, it forms a force couple that rotates the shoulder blade smoothly during arm elevation. It also helps support the weight of the head and arms throughout the day.', 'Commonly short and overactive. It tends to stay switched on in people who sit at desks, carry bags on one shoulder, or hold tension through the neck and shoulders, often producing a raised, hunched look. Because it is so easy to over-recruit, it frequently dominates movements that the deeper and lower scapular muscles should share. In screening it is far more often flagged as tight than weak; resting length and tone are the usual concern.', NULL, NULL)
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('anterior-deltoid', 'anterior_imbalanced_shoulders', 'tight', 'Press-dominant training tends to overbuild the anterior deltoid relative to the muscles that pull the shoulder back, so it sits short and overactive in anterior imbalanced shoulders. Because it crosses the front of the joint, a tight anterior deltoid helps hold the upper arm flexed and rolled inward, reinforcing the forward shoulder position. Easing its tone and rebalancing it against the back-of-shoulder muscles helps the joint re-center.', 'low', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('deep-abdominals', 'trunk_lean', 'weak', 'The abdominal wall is the main counterweight to the back extensors: when the deep abdominals are lengthened and slow to engage, the back extensors dominate and the trunk drifts — the upper thoracic spine tips backward with the chest flared while the hips slide forward and the lumbar curve deepens. The common thread is an abdominal wall that cannot draw the ribcage down, tilt the pelvis, and stack the trunk back over the hips. Rebuilding the ability to brace the front of the trunk may benefit how the whole column re-centers over the pelvis.', 'medium', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('deep-cervical-flexors', 'forward_head_posture', 'weak', 'The deep cervical flexors are the muscles that should hold the head balanced over the spine and keep the chin gently tucked. When they lose endurance and strength, the head drifts forward and larger surface muscles take over head support, letting the chin poke out. Because little is holding the cervical curve from the inside, the forward-head position settles in. Rebuilding their endurance helps the client hold a centered head position.', 'high', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('gastrocnemius-soleus', 'trunk_lean', 'tight', 'When the pelvis and body sway forward over the feet, the calf (gastrocnemius and soleus) fires constantly to keep the body from toppling, and over time it shortens. Prolonged standing sway, high heels, and a forward center of mass all load the calf this way. Releasing and lengthening it helps the body re-balance back over the midfoot rather than hanging forward at the ankles.', 'medium', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('gastrocnemius-soleus', 'knee_extension_back_knee', 'tight', 'In a back-knee (hyperextended) pattern the calf — especially the gastrocnemius, which crosses the knee — pulls on the back of the joint and helps hold it locked into full extension. High heels and a backward-shifted center of mass reinforce this backward pull. Lengthening the calf reduces the tension behind the knee and lets the joint rest in a softer, neutral position.', 'medium', false, 'Display-only: the calf to recurvatum link rests on stroke-population and direction-ambiguous evidence (Grade C), below the asymptomatic-population bar the hamstring link cleared, so it is kept educational rather than scored.');
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('gluteus-maximus', 'trunk_lean', 'weak', 'Considered as part of the gluteal complex as a whole, weak hip extensors let the pelvis drift forward of the feet in an anterior pelvic shift. The gluteus maximus ordinarily anchors the back of the pelvis down and drives the hips back under the trunk; when it is under-active, the short hip flexors win and the pelvis stays shifted and tilted. Waking it up may help restore the back-of-hip pull that draws the pelvis back toward the base of support. The gluteus medius contributes here too and is covered under its own links.', 'high', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('gluteus-medius', 'pelvic_obliquity', 'tight', 'On the side opposite the elevated hip, the gluteus medius tends to become short and overactive, bearing more standing load and holding the opposite side of the pelvis up, reinforcing the obliquity. Because it is the overactive partner here, it usually benefits from release and length work rather than added strengthening — the elevated-side medius is the one that needs waking up.', 'low', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('gluteus-medius', 'pelvic_obliquity', 'weak', 'On the elevated (higher) side of the pelvis, the gluteus medius sits in a lengthened, stretched position and loses the strength and timing needed to hold the pelvis level, so the obliquity is reinforced through the day. In screening it shows as a pelvis that cannot stay level in single-leg stance on this side, and it typically benefits from targeted strengthening and re-timing.', 'high', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('gluteus-medius', 'genu_varum_valgum_left', 'weak', 'On the left side, a weak gluteus medius lets the thigh bone drift inward and rotate in during weight-bearing, allowing the knee to fall toward the midline — the knee-drifting-inward (knock-knee) tendency — and weakening the frontal-plane control that should also keep a bow-knee in check. The medius is the main stabilizer sitting above the knee at the hip. Strengthening the left gluteus medius may help improve how the thigh tracks over the foot during standing and gait.', 'high', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('gluteus-medius', 'genu_varum_valgum_right', 'weak', 'On the right side, a weak gluteus medius lets the thigh bone drift inward and rotate in during weight-bearing, allowing the knee to fall toward the midline — the knee-drifting-inward (knock-knee) tendency — and weakening the frontal-plane control that should also keep a bow-knee in check. The medius is the main stabilizer sitting above the knee at the hip. Strengthening the right gluteus medius may help improve how the thigh tracks over the foot during standing and gait.', 'high', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('hamstrings', 'trunk_lean', 'weak', 'When the pelvis sways forward of the ankles, the hamstrings (alongside the glutes and deep abdominals) lengthen and lose the leverage to draw the pelvis back over the feet. Prolonged standing sway and a center of mass carried forward leave the back of the thigh underactive, so the front of the hip dominates the standing posture. Strengthening the hamstrings helps pull the pelvis back into a stacked position over the midfoot.', 'low', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('hamstrings', 'knee_extension_back_knee', 'weak', 'The hamstrings bend the knee and resist it snapping into full extension, so in a back-knee (hyperextended) pattern they often test weak and let the joint settle into its locked end-range. With the quadriceps holding the knee backward and the hamstrings underactive, the joint loses its dynamic brake against hyperextension. Strengthening the hamstrings helps the knee hold a soft, neutral position under load.', 'medium', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('hip-adductors', 'pelvic_obliquity', 'tight', 'On the elevated (higher) side of the pelvis, the inner-thigh adductors sit shortened and tend to become overactive, helping draw that side of the pelvis upward and holding the obliquity in place alongside the same-side quadratus lumborum. Because they are short and overactive here, the elevated-side adductors generally benefit from release and length work rather than strengthening.', 'medium', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('hip-adductors', 'genu_varum_valgum_left', 'tight', 'Adductor involvement on the left applies specifically in the knock-knee (knee-drifting-inward) presentation. When the left knee collapses toward the midline, the inner-thigh adductors sit shortened and overactive, reinforcing the inward pull of the thigh. In the bow-knee (knee-bowing-outward) presentation it is the lateral structures, not the adductors, that tighten. Lengthening the left adductors helps the thigh track back out over the foot.', 'low', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('hip-adductors', 'genu_varum_valgum_right', 'tight', 'Adductor involvement on the right applies specifically in the knock-knee (knee-drifting-inward) presentation. When the right knee falls toward the midline, the inner-thigh adductors are held short and overactive, reinforcing the inward pull on the thigh. In the bow-knee (knee-bowing-outward) presentation the lateral structures tighten instead, not the adductors. Releasing and lengthening the right adductors helps the thigh track back out over the foot.', 'low', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('iliopsoas', 'trunk_lean', 'tight', 'In an anterior pelvic shift the hips drift forward of the midline and the pelvis often tips into the bargain. A short, overactive iliopsoas is one contributor: pulling from its spine and pelvis attachments, it holds the hip flexed and tugs the pelvis into that forward, tilted position. As long as it stays tight it resists the hip extension needed to bring the pelvis back over the feet, so lengthening it is usually a first step before the glutes and deep abdominals can re-balance the position.', 'high', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('latissimus-dorsi', 'trunk_lean', 'tight', 'Because the latissimus dorsi anchors to the lower spine and pelvis and pulls on the upper arm and ribcage, a short lat tilts the ribcage upward and feeds extension into the spine, adding to a backward T1 tilt of the upper trunk. When clients reach overhead, a tight lat arches the mid-back rather than letting the arms rise freely, exaggerating the backward lean. Lengthening the lat reduces this extension pull and may benefit the way the ribcage settles down over the pelvis.', 'low', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('levator-scapulae', 'forward_head_posture', 'tight', 'With the head held forward of the shoulders, the levator scapulae stays loaded as it helps support the neck and steady the head. Its attachment on the upper neck vertebrae means a forward-head position keeps it under sustained tension, shortening it over time and adding to the stiffness felt along the side and base of the neck. Lengthening it supports a more centered head position over the spine.', 'low', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('levator-scapulae', 'posterior_imbalanced_shoulders', 'tight', 'Posterior imbalanced shoulders involve a shoulder that sits hiked or elevated. The levator scapulae is a direct elevator of the shoulder blade, so a chronically raised shoulder keeps these fibers shortened and overactive on the affected side. Because it also tips the inner corner of the shoulder blade, ongoing tension can hold the blade in a less efficient resting position; easing it helps the shoulder settle toward a level height.', 'medium', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('lower-trapezius', 'forward_head_posture', 'weak', 'The lower trapezius helps anchor the shoulder blades down and supports an upright upper back that lets the head stack over the shoulders. When it is under-active, the shoulder blades ride up, the upper back rounds, and the head is carried further forward. Because it counterbalances the overworked upper trapezius, restoring its strength supports a more upright posture and a centered head position.', 'medium', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('lower-trapezius', 'anterior_imbalanced_shoulders', 'weak', 'When the shoulders round forward, the lower trapezius is held long and switched off, so it cannot draw the shoulder blades down and back. The upper trapezius and chest muscles then dominate, pulling the shoulders up and forward, and uneven activity side to side can leave one shoulder more forward than the other. Strengthening the lower trapezius helps set the shoulder blades down and back and level the shoulders.', 'high', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('lower-trapezius', 'posterior_imbalanced_shoulders', 'weak', 'Posterior imbalanced shoulders involve a shoulder that sits hiked and elevated. The lower trapezius is the main muscle that pulls the shoulder blade downward, so when it is weak the elevators (upper trapezius and levator scapulae) go unopposed and the shoulder rides high. Strengthening the lower fibers may help restore the downward pull that supports a more level resting shoulder height.', 'high', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('lumbar-erector-spinae', 'trunk_lean', 'tight', 'When the pelvis drifts forward of the ankles in an anterior pelvic shift, the upper trunk counter-leans backward to stay balanced, and the lumbar erector spinae shorten to hold that arched low-back position. Their overactivity deepens the lumbar curve and keeps the trunk tipped back, working opposite the deep abdominals that would otherwise level the pelvis. Restoring their length, while rebuilding abdominal support, may benefit the way the hips return under the ribcage and shoulders.', 'high', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('middle-trapezius', 'anterior_imbalanced_shoulders', 'weak', 'When the shoulders round and drift forward, the middle trapezius sits in a lengthened position and loses its ability to draw the shoulder blades back toward the spine. With this retractor switched off, the tight chest muscles win and the shoulders settle further forward, and any side-to-side difference in its activity can leave one shoulder more forward than the other. Strengthening it helps pull the shoulder blades back and level the shoulders.', 'medium', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('pectoralis-major', 'anterior_imbalanced_shoulders', 'tight', 'With anterior imbalanced shoulders, the upper arm sits rolled forward and inward, which is exactly the position a short pectoralis major holds it in. Desk work and press-dominant training keep this muscle contracted, so it shortens and continuously tugs the shoulder toward the front of the body. Lengthening it through the chest helps the shoulder settle back over the ribcage and gives the mid-back muscles a fair chance to hold position.', 'medium', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('pectoralis-minor', 'anterior_imbalanced_shoulders', 'tight', 'A short pectoralis minor tips the shoulder blade forward and pulls it around the ribcage, which is a direct driver of anterior imbalanced shoulders. Because it attaches to the shoulder blade rather than the arm, its tightness keeps the whole shoulder rounded forward even when the chest is relaxed. Releasing it lets the shoulder blade settle flat and back, which is hard to achieve while this deep muscle stays locked short.', 'high', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('popliteus', 'knee_extension_back_knee', 'weak', 'The popliteus is responsible for unlocking the knee out of full extension, so in a back-knee (hyperextended) pattern it is frequently underactive — the joint stays locked and the muscle is never recruited to free it. Joint laxity and a backward-shifted center of mass reinforce the locked position and let the popliteus go quiet. Activating it helps the knee break out of its end-range and settle into a softer, neutral alignment.', 'low', false, 'Display-only: no causal recurvatum data supports the popliteus inference (Grade C+); it stays on the muscle page as education but is excluded from the scored map alongside the calf and quadriceps links.');
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('quadratus-lumborum', 'pelvic_obliquity', 'tight', 'In pelvic obliquity one hip sits higher than the other, and the quadratus lumborum on the elevated side is typically short and overactive, hiking that side of the pelvis up toward the lowest rib. Because it directly bridges the iliac crest and the rib, sustained side-bending or one-sided weight-bearing keeps this side shortened and tips the pelvis into the tilt. Easing its tone on the elevated side, while restoring support underneath the pelvis, may benefit the way the hips level out.', 'high', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('quadriceps', 'knee_extension_back_knee', 'tight', 'In a back-knee (hyperextended) standing pattern, the quadriceps hold the knee jammed into full extension rather than letting it rest in a soft, neutral position. High heels, joint laxity, and a center of mass carried backward all push the knee into this locked posture, and the quadriceps shorten to keep it there. Releasing front-thigh tension helps the knee settle out of its locked end-range.', 'low', false, 'Display-only: the quadriceps to recurvatum inference is the weakest of the four (Grade D) and could not be supported in the 2026-06-27 evidence scan, so it is kept educational and excluded from the scored map.');
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('quadriceps', 'genu_varum_valgum_left', 'weak', 'When the left knee drifts into a bowed or knock-kneed alignment, the quadriceps — particularly the vastus medialis oblique (VMO) on the inner knee — often test underactive and stop steering the kneecap. A weak VMO lets the patella slide off-track and the knee collapse toward the midline or bow outward. Strengthening the inner quad helps the left kneecap track centrally and supports a more vertical knee line.', 'medium', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('quadriceps', 'genu_varum_valgum_right', 'weak', 'When the right knee drifts into a bowed or knock-kneed alignment, the quadriceps — particularly the vastus medialis oblique (VMO) on the inner knee — often test underactive and stop steering the kneecap. A weak VMO lets the patella slide off-track and the knee collapse toward the midline or bow outward. Strengthening the inner quad helps the right kneecap track centrally and supports a more vertical knee line.', 'medium', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('rectus-femoris', 'trunk_lean', 'tight', 'As a two-joint muscle anchored to the front of the pelvis, a short rectus femoris can contribute, as one of the hip flexors, to a forward pelvic tilt and to the hips carrying ahead of the ankles in an anterior pelvic shift. The evidence frames it as part of the hip-flexor group rather than in isolation — easing hip-flexor tightness measurably reduces the forward tilt, but the effect is modest and cannot be pinned to the rectus femoris alone. It is therefore graded medium-confidence and addressed together with the iliopsoas.', 'medium', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('rhomboids', 'anterior_imbalanced_shoulders', 'weak', 'In anterior imbalanced shoulders the rhomboids are stretched long and underactive, so they lose the tug-of-war against tight chest muscles and the shoulder blades slide forward. Without their steady retraction, the shoulder blade drifts away from the spine and the shoulder rounds toward the front. Strengthening them may help restore a counterpull that holds the shoulder blades back and supports re-centering the shoulders over the ribcage.', 'low', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('serratus-anterior', 'anterior_imbalanced_shoulders', 'weak', 'In anterior imbalanced shoulders a weak serratus anterior cannot keep the shoulder blade flat and properly rotated against the ribcage, so the blade loses its stable seat and the shoulder rounds forward. Poor serratus control also lets the inner edge of the blade lift away (winging), which worsens the forward shoulder position. Rebuilding its strength and timing may help give the shoulder blade a flatter, more stable base, so the shoulder can sit back more easily.', 'high', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('sternocleidomastoid', 'forward_head_posture', 'tight', 'In a forward-head position the lower neck bends forward while the head tips back slightly to keep the eyes level, and the sternocleidomastoid is well placed to drive and hold this combination. Relying on the SCM rather than the deeper neck flexors keeps it short and overactive, and it can become visibly prominent at rest. Easing its tone while rebuilding deep-flexor support helps the head re-center over the spine.', 'high', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('suboccipitals', 'forward_head_posture', 'tight', 'When the head drifts forward of the shoulders, the eyes still need to stay level, so the suboccipitals hold the skull tipped back in sustained extension. Over time this constant holding shortens them, reinforcing the forward-head position and making it feel "normal" to the client. Releasing and lengthening them helps the head re-center over the spine.', 'medium', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('tfl-it-band', 'genu_varum_valgum_left', 'tight', 'On the left, the TFL and IT band are the lateral structures whose tightness applies specifically in the bow-knee (knee-bowing-outward) presentation. When the left knee bows outward, this outer-thigh unit sits shortened and overactive, reinforcing the lateral pull. In the knock-knee (knee-drifting-inward) presentation it is the inner-thigh adductors that tighten instead. Releasing the left TFL and IT band helps the knee and thigh track back toward neutral alignment.', 'medium', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('tfl-it-band', 'genu_varum_valgum_right', 'tight', 'On the right, the TFL and IT band are the lateral structures whose tightness applies specifically in the bow-knee (knee-bowing-outward) presentation. When the right knee bows outward, this outer-thigh unit is held short and overactive, reinforcing the lateral pull. In the knock-knee (knee-drifting-inward) presentation the inner-thigh adductors tighten instead. Releasing and lengthening the right TFL and IT band helps the knee and thigh track back toward neutral alignment.', 'medium', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('thoracic-erector-spinae', 'trunk_lean', 'tight', 'In a backward T1 tilt the upper trunk leans behind the hips, and the thoracic erector spinae hold that extended position, shortening on both sides to keep the chest lifted and the mid-back arched. Because they actively pull the thoracic spine into extension, sustained overactivity here reinforces the backward lean and limits the forward give needed to re-stack the ribcage over the pelvis. Easing their tone and restoring mid-back flexion may benefit the way the upper trunk settles back over the spine.', 'low', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('upper-trapezius', 'forward_head_posture', 'tight', 'As the head drifts forward of the shoulders, the upper trapezius works harder to hold the heavier load of the head against gravity and to keep the eyes level. Sustained low-level activity in this position shortens the upper fibers and raises their resting tone, which adds to the pull on the neck and reinforces the forward-head pattern. Easing this tension supports re-centering the head over the spine.', 'high', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('upper-trapezius', 'anterior_imbalanced_shoulders', 'tight', 'When the shoulders round and drift forward, the upper trapezius often over-works to stabilize and elevate the shoulder blade in place of the weaker mid- and lower-trapezius fibers. This over-reliance keeps the upper fibers short and tense, and when one side is loaded or leaned on more than the other it can hold that shoulder higher and further forward. Releasing it lets the lower scapular muscles re-engage.', 'high', true, NULL);
INSERT INTO muscle_imbalance_links (muscle_slug, imbalance_key, role, rationale_text, link_evidence, scored, exclusion_reason) VALUES ('upper-trapezius', 'posterior_imbalanced_shoulders', 'tight', 'Posterior imbalanced shoulders involve a shoulder that sits elevated or hiked upward. The upper trapezius is a primary elevator of the shoulder blade, so chronic hiking, one-sided carrying, or guarding keeps these fibers shortened and overactive on the affected side. Sustained elevation is exactly what the upper trapezius produces, so reducing its tone helps the shoulder settle back toward a level resting height.', 'high', true, NULL);
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('band-hip-hinge-pull-through', 'Band Hip Hinge Pull-Through', 'strengthen', ARRAY['trunk_lean'], 'warning', 'Stand facing away from a low band anchor with the band running between your legs and held in both hands. Push your hips back to hinge forward, keeping a flat back and a soft bend in the knees. Then drive your hips forward to stand tall, squeezing your glutes at the top. Move with control and let the hips do the work. Perform 10-15 repetitions per set.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('band-lying-hip-internal-rotation', 'Band Lying Hip Internal Rotation', 'strengthen', ARRAY['pelvic_axial_rotation'], 'warning', 'Lie on your side or sit with the working knee bent and a light band providing gentle resistance to the lower leg. Rotate the lower leg to turn the hip inward with control, moving only through a comfortable range. Pause 2 seconds at the end of the turn, then return slowly to the start. Keep the hips stacked and steady so the movement comes from the hip. Perform 10-12 controlled repetitions, then switch sides.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('band-pull-apart', 'Band Pull-Apart', 'strengthen', ARRAY['anterior_imbalanced_shoulders'], 'warning', 'Stand tall holding a light resistance band at shoulder height, hands about shoulder-width apart, arms straight. Pull the band apart by drawing your hands outward until it touches your chest, squeezing the shoulder blades together. Pause 2 seconds at full squeeze, then return with control. Keep the ribs down and avoid shrugging toward the ears. Perform 10-15 controlled repetitions per set.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('band-rear-delt-row', 'Band Rear Delt Row', 'strengthen', ARRAY['posterior_imbalanced_shoulders'], 'warning', 'Stand tall facing a band anchored at about chest height, holding one end in each hand with arms extended forward. Row your elbows high and wide toward the rear, drawing your shoulder blades together as your hands travel back. Pause briefly at the fullest squeeze, then return your arms forward slowly with control. Keep your ribs down and your neck relaxed, letting the mid-back do the work. Perform 10-15 controlled repetitions per set.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('band-reverse-fly', 'Band Reverse Fly', 'strengthen', ARRAY['posterior_imbalanced_shoulders'], 'warning', 'Stand with feet hip-width apart and hinge forward slightly at the hips, holding a light band anchored in front of you at chest height with straight arms. Sweep both arms out to the sides in a wide arc like a reverse fly, drawing the shoulder blades together at the top. Pause 2 seconds at the widest point, then return slowly to the start with control. Keep the ribs down and the neck long throughout. Perform 10-15 controlled repetitions per set.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('bent-knee-calf-stretch', 'Bent-Knee Calf Stretch', 'stretch', ARRAY['knee_extension_back_knee', 'trunk_lean'], 'maintain', 'Stand facing a wall with hands on it for support. Step one foot back a half stride, keeping the heel down and toes forward. This time bend the back knee, sinking it toward the wall while the heel stays planted, until you feel the stretch move lower and deeper in the calf, toward the heel cord. Keep the trunk upright and weight even across the back foot. Hold 30 seconds, then change sides.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('bird-dog', 'Bird Dog', 'strengthen', ARRAY['trunk_lean', 'pelvic_axial_rotation'], 'warning', 'Start on hands and knees, wrists under shoulders and knees under hips, spine in a comfortable mid position. Brace the abdominals lightly, then reach one arm forward and the opposite leg back until both are level with the trunk. Keep the hips square to the floor — imagine balancing a cup of water on the lower back. Hold 5 seconds, return slowly, and switch sides. Do 6-8 repetitions per side, moving with control rather than speed.', 3, 5, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('butterfly-stretch', 'Butterfly Stretch', 'stretch', ARRAY['pelvic_obliquity', 'genu_varum_valgum_left', 'genu_varum_valgum_right'], 'maintain', 'Sit tall on the floor with the soles of your feet together and knees dropped out to the sides. Hold your ankles and rest the elbows lightly on the inner thighs. Sit up out of the lower back, then hinge slightly forward from the hips — or let the elbows press the thighs gently toward the floor — until you feel a stretch along the inner thighs and groin. Avoid bouncing. Hold 30 seconds while breathing slowly, then release.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('cat-cow', 'Cat-Cow', 'mobility', ARRAY['trunk_lean', 'forward_head_posture'], 'maintain', 'Start on hands and knees with wrists under shoulders and knees under hips. Exhale and round your spine toward the ceiling, tucking the tailbone and letting the head drop (cat). Inhale and reverse, letting the belly sink while the chest and tailbone lift (cow). Move slowly segment by segment, pausing 3 seconds at each end position. Keep the arms straight and the movement smooth. Flow through 8-10 full cycles per set.', 2, 3, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('childs-pose-reach', 'Child''s Pose with Overhead Reach', 'stretch', ARRAY['trunk_lean'], 'maintain', 'Kneel on a mat, sit your hips back toward your heels, and walk your hands forward until your chest sinks toward the floor. Keep the arms long and reach the fingertips as far forward as comfortable to lengthen the sides of the back. Let the spine round gently and breathe into the back ribs. For more side emphasis, walk both hands toward one side and hold. Stay 30 seconds per hold, then slowly rise.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('chin-tuck-head-lift', 'Chin Tuck with Head Lift', 'strengthen', ARRAY['forward_head_posture'], 'warning', 'Lie on your back with knees bent. First perform a gentle chin nod, drawing the chin toward the throat. Keeping that nod, lift your head just one to two centimeters off the floor — barely clearing it. Hold 5 seconds without letting the chin poke forward, then lower with control. If the front of your neck shakes early, build up with shorter holds first. Rest briefly between repetitions.', 3, 5, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('chin-tucks', 'Chin Tucks', 'strengthen', ARRAY['forward_head_posture'], 'warning', 'Stand or sit tall. Gently retract your chin straight back, making a double chin. Hold 5 seconds, then release. Perform 10-12 repetitions per set.', 3, 5, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('clamshell', 'Clamshell', 'strengthen', ARRAY['pelvic_obliquity', 'genu_varum_valgum_left', 'genu_varum_valgum_right'], 'warning', 'Lie on your side with knees stacked and bent at 45 degrees. Keeping your feet together, open your top knee upward like a clamshell. Pause, then lower slowly. Perform 10-12 repetitions per set, then switch sides.', 3, 5, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('dead-bug', 'Dead Bug', 'strengthen', ARRAY['trunk_lean'], 'warning', 'Lie on your back with arms reaching toward the ceiling and hips and knees bent to 90 degrees, shins parallel to the floor. Press your lower back gently into the mat. Slowly lower one arm overhead and the opposite leg toward the floor, stopping before the lower back lifts. Pause 3 seconds, return, and switch sides. Move only as far as you can keep the trunk completely still. Do 6-8 slow repetitions per side, per set.', 3, 3, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('doorway-pec-stretch', 'Doorway Pec Stretch', 'stretch', ARRAY['anterior_imbalanced_shoulders'], 'maintain', 'Stand in a doorway. Place your forearm on the door frame with elbow at 90 degrees. Step forward gently until you feel a stretch across your chest. Hold 30 seconds. Repeat on the other side.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('figure-four-stretch', 'Supine Figure-Four Stretch', 'stretch', ARRAY['pelvic_axial_rotation'], 'maintain', 'Lie on your back with knees bent and feet flat. Cross one ankle over the opposite thigh, just above the knee, letting the crossed knee fall open. Reach through and clasp behind the supporting thigh, then gently pull it toward your chest until you feel a stretch deep in the buttock of the crossed leg. Keep your head and shoulders on the floor and the tailbone heavy. Hold 30 seconds, release slowly, and switch sides.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('foam-roll-lateral-thigh', 'Foam Rolling: Lateral Thigh', 'mobility', ARRAY['genu_varum_valgum_left', 'genu_varum_valgum_right'], 'maintain', 'Lie on your side with a foam roller under the outside of your thigh, just below the hip, supporting yourself on your forearm. Place the top leg over and in front for support. Roll slowly from below the hip bone toward just above the knee and back, pausing 5-10 seconds on tight or restricted spots and letting the tissue soften. Keep the pressure firm but tolerable — ease off by taking more weight through the arms. Spend about 45-60 seconds per side.', 2, 45, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('front-plank', 'Front Plank', 'strengthen', ARRAY['trunk_lean'], 'warning', 'Lie face down, then prop yourself on your forearms and toes with elbows under the shoulders. Tuck the tailbone slightly and brace the abdominals so the body forms one straight line from head to heels — no sagging hips, no pike. Breathe steadily throughout the hold; if the lower back starts to dip, rest and restart from the knees. Hold 20-30 seconds per set, building duration gradually as control improves.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('glute-bridge-march', 'Glute Bridge March', 'strengthen', ARRAY['trunk_lean', 'pelvic_obliquity'], 'warning', 'Set up in a glute bridge with your hips lifted and glutes squeezed. Holding that height, lift one foot off the floor, then set it down and lift the other, marching slowly and steadily. Keep your hips level and still the whole time so the pelvis does not dip or rotate. Count each leg lift as one repetition per leg. Perform 8-12 repetitions per leg per set.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('glute-bridge', 'Glute Bridge', 'strengthen', ARRAY['trunk_lean', 'knee_extension_back_knee'], 'maintain', 'Lie on your back with knees bent and feet flat on the floor. Squeeze your glutes and drive your hips up until your body forms a straight line from knees to shoulders. Hold 2 seconds at the top. Lower slowly. Perform 10-12 repetitions per set.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('half-kneeling-band-chop', 'Half-Kneeling Band Chop', 'strengthen', ARRAY['pelvic_axial_rotation'], 'warning', 'Set up in a half-kneeling position with a band anchored high to one side. Hold the band with both hands and draw it down and across your body slowly and with control, keeping the motion smooth rather than ballistic. Pause 2 seconds at the bottom, then guide the band back up with the same control. Keep your hips and torso tall and steady throughout. Perform 8-12 slow repetitions, then switch sides.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('hands-behind-back-chest-opener', 'Hands-Behind-Back Chest Opener', 'stretch', ARRAY['anterior_imbalanced_shoulders'], 'maintain', 'Stand tall and interlace your fingers behind your lower back, palms facing in. Straighten the elbows, roll the shoulders back and down, and gently lift the hands away from your body until you feel a stretch across the front of the shoulders and chest. Keep the chin level and ribs stacked over the pelvis — avoid arching the lower back to cheat the lift. Hold 30 seconds, breathing slowly, then release.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('high-band-pull-apart', 'High Band Pull-Apart', 'strengthen', ARRAY['trunk_lean', 'posterior_imbalanced_shoulders'], 'warning', 'Stand tall holding a light resistance band overhead at about eye or forehead level, hands roughly shoulder-width apart. Pull the band apart and downward, sweeping your arms into a wide "V" while drawing your shoulder blades down toward your back pockets. Pause briefly at the bottom of the V, then return the band overhead with control. Keep your ribs down and your neck relaxed throughout. Perform 10-15 controlled repetitions per set.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('kneeling-hip-flexor-stretch', 'Kneeling Hip Flexor Stretch', 'stretch', ARRAY['trunk_lean', 'pelvic_obliquity'], 'warning', 'Kneel with one knee on the ground and the other foot forward (lunge position). Shift your hips forward until you feel a stretch in the front of the hip. Keep your back straight. Hold 30 seconds. Repeat on the other side.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('kneeling-lat-stretch', 'Kneeling Lat Stretch on Chair', 'stretch', ARRAY['trunk_lean'], 'maintain', 'Kneel in front of a chair or bench and place both elbows on it, hands together and thumbs pointing toward the ceiling. Sit your hips back toward your heels while letting your chest sink between the arms until you feel a stretch along the sides of your upper back and under the arms. Keep the lower ribs drawn gently in so the stretch stays in the lats rather than the lower back. Hold 30 seconds, breathing slowly, then ease out.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('knees-to-chest-stretch', 'Knees-to-Chest Stretch', 'stretch', ARRAY['trunk_lean'], 'maintain', 'Lie on your back on a mat. Draw both knees up and hug them toward your chest with your hands behind the thighs or over the shins. Let your lower back relax and gently round into the floor, and keep your head and shoulders resting down. You should feel an easy stretch across the lower back and hips. Hold 30 seconds while breathing slowly, then lower one leg at a time. Rock gently side to side during the hold if that feels comfortable.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('lateral-band-walk', 'Lateral Band Walk', 'strengthen', ARRAY['genu_varum_valgum_left', 'genu_varum_valgum_right', 'pelvic_obliquity'], 'warning', 'Place a loop band just above your knees (or around the ankles for more challenge). Sit into a quarter-squat with feet hip-width apart, chest up. Step sideways with one foot, then follow with the other, keeping constant tension on the band and the knees tracking over the toes — never letting them cave inward. Take 8-10 steps in one direction, pause 2 seconds, then return leading with the other leg. Stay low throughout the set.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('levator-scapulae-stretch', 'Levator Scapulae Stretch', 'stretch', ARRAY['forward_head_posture', 'posterior_imbalanced_shoulders'], 'maintain', 'Sit tall and grasp the edge of your chair with one hand to anchor the shoulder down. Turn your head about 45 degrees away from that side, then look down toward your opposite armpit. Place your free hand lightly on the back of your head and add gentle pressure until you feel a stretch along the back-side of the neck into the shoulder blade. Hold 30 seconds, release slowly, and repeat on the other side.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('neck-lateral-stretch', 'Neck Lateral Stretch', 'stretch', ARRAY['forward_head_posture'], 'maintain', 'Tilt your head to one side, ear toward shoulder. Gently apply light pressure with your hand. Hold 30 seconds. Repeat on the other side.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('open-book-stretch', 'Open Book Stretch', 'mobility', ARRAY['pelvic_axial_rotation'], 'maintain', 'Lie on your side with knees bent to 90 degrees and stacked, arms extended together in front of your chest. Keeping the knees glued together on the floor, lift the top arm and rotate it across your body toward the opposite side, letting the chest and trunk open like a book. Follow the moving hand with your eyes. Pause 3-5 seconds at your comfortable end range, feeling the stretch through the waist and trunk, then return. Do 8-10 rotations, then switch sides.', 2, 5, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('pallof-press', 'Pallof Press (Anti-Rotation Hold)', 'strengthen', ARRAY['pelvic_axial_rotation'], 'warning', 'Anchor a resistance band at chest height and stand side-on to the anchor, holding the band with both hands at your sternum, feet hip-width apart. Press the hands straight out in front of your chest and hold — the band will try to twist you toward the anchor; resist so the hips and shoulders stay square. Hold 10 seconds, return the hands to the chest, and repeat 8 times, then face the other way. Soften the knees and keep breathing through every hold.', 3, 10, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('prone-cobra-hold', 'Prone Cobra Hold', 'strengthen', ARRAY['trunk_lean', 'posterior_imbalanced_shoulders'], 'warning', 'Lie face down with your forehead resting lightly on the floor and arms alongside your body. Gently lift your chest and both hands off the floor, rotating your thumbs upward toward the ceiling. Draw your shoulder blades down and back to open the front of your chest, keeping your neck long and gaze toward the floor. Hold this position steadily for 10 seconds while breathing normally, then lower with control. Repeat for 3 holds per set.', 3, 10, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('prone-hamstring-curl', 'Prone Hamstring Curl', 'strengthen', ARRAY['knee_extension_back_knee'], 'warning', 'Lie face down on a mat with legs straight and forehead resting on your hands. Keeping the hips pressed into the floor, slowly bend one knee, bringing the heel toward your glutes over a count of two. Pause 3 seconds at the top, then lower over a count of three. Avoid lifting the hip or rocking the pelvis as the knee bends. Do 10-12 repetitions per leg; add a light ankle weight or loop band when it becomes easy.', 3, 3, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('prone-hip-extension', 'Prone Hip Extension with Abdominal Brace', 'strengthen', ARRAY['trunk_lean'], 'warning', 'Lie face-down with a flat cushion under your hips and your forehead resting on your hands. First draw the lower belly gently up and away from the floor — an abdominal brace — and hold it there so the lower back stays quiet. Keeping that brace, squeeze one glute and lift that straight leg a few inches off the floor, leading with the heel and without arching the back or rotating the pelvis. Hold 5 seconds, lower with control, and repeat for 8-10 reps before switching sides.', 3, 5, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('prone-i-raise', 'Prone I Raise', 'strengthen', ARRAY['posterior_imbalanced_shoulders', 'trunk_lean'], 'warning', 'Lie face down with your arms reaching straight overhead in a narrow "I" shape, thumbs pointing up toward the ceiling. Keeping your arms long and your neck relaxed, lift both arms toward the ceiling by drawing your shoulder blades down and together. Pause briefly at the top, then lower slowly with control. Focus the effort in your mid and lower back rather than your neck or hands. Perform 8-12 controlled repetitions per set.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('prone-t-raise', 'Prone T-Raise', 'strengthen', ARRAY['anterior_imbalanced_shoulders', 'posterior_imbalanced_shoulders'], 'warning', 'Lie face down with your forehead on a folded towel and arms out to the sides in a T shape, thumbs pointing up. Squeeze your shoulder blades together and down, then lift both arms a few centimeters off the floor without lifting your chest or shrugging. Hold 3 seconds at the top, then lower slowly. Keep the neck long and gaze at the floor. Perform 8-12 repetitions per set; add light weights to progress further.', 3, 3, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('prone-w-raise', 'Prone W Raise', 'strengthen', ARRAY['posterior_imbalanced_shoulders'], 'warning', 'Lie face down with your elbows bent and tucked toward your sides so your arms form a "W" shape. Keeping your neck long, lift your arms and chest slightly while squeezing your shoulder blades together and down. Pause briefly at the top to feel the mid-back working, then lower slowly with control. Keep the motion smooth and let your shoulder blades lead rather than your hands. Perform 8-12 controlled repetitions per set.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('prone-y-raise', 'Prone Y-Raise', 'strengthen', ARRAY['anterior_imbalanced_shoulders', 'posterior_imbalanced_shoulders', 'forward_head_posture'], 'warning', 'Lie face down with your forehead on a folded towel and arms extended overhead at roughly 45 degrees, forming a Y, thumbs pointing up. Draw the shoulder blades down toward your back pockets, then lift both arms a few centimeters off the floor. Hold 3 seconds, feeling the work low between the shoulder blades rather than in the upper neck, then lower with control. Perform 8-12 repetitions per set.', 3, 3, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('push-up-plus', 'Push-Up Plus', 'strengthen', ARRAY['anterior_imbalanced_shoulders'], 'warning', 'Start in a push-up position with hands under the shoulders and body in one straight line (drop to the knees to reduce the load). At the top of the position, keep the elbows straight and push the floor away, spreading your shoulder blades apart so the upper back rounds slightly. Hold 2 seconds, then lower the chest a few centimeters and repeat the push. Keep the core braced so the hips stay level. Perform 8-12 repetitions per set.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('quadruped-thoracic-rotation', 'Quadruped Thoracic Rotation', 'mobility', ARRAY['trunk_lean'], 'maintain', 'Start on your hands and knees and place one hand behind your head. Rotate that elbow up toward the ceiling, opening your chest and following the elbow with your eyes. Then reach the same elbow down and under your body, letting your upper back round gently. Move smoothly through the full range and count each rotation as one repetition per side. Switch sides. Perform 8-10 repetitions per side per set.', 2, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('rear-deltoid-stretch', 'Rear Deltoid Stretch', 'stretch', ARRAY['posterior_imbalanced_shoulders'], 'maintain', 'Stand or sit tall and draw one arm horizontally across the front of your chest. Use the opposite forearm to gently guide it closer to your body until you feel a stretch across the back of the shoulder. Keep the shoulder relaxed and down rather than shrugging it toward your ear. Hold 30 seconds while breathing steadily, then release and repeat on the other side.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('seated-band-row', 'Seated Band Row', 'strengthen', ARRAY['anterior_imbalanced_shoulders'], 'warning', 'Sit on the floor with legs extended and loop a resistance band around your feet, holding one end in each hand. Sit tall, then pull the band toward your lower ribs, driving the elbows back and squeezing the shoulder blades together. Pause 2 seconds, then let the arms return slowly without letting the shoulders roll forward. Keep the torso upright the whole time. Perform 10-12 repetitions per set.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('seated-hamstring-stretch', 'Seated Hamstring Stretch', 'stretch', ARRAY['knee_extension_back_knee'], 'maintain', 'Sit on the floor with one leg extended straight in front of you and the other leg relaxed. Hinge forward from your hips over the straight leg, keeping your back long rather than rounded, until you feel a gentle stretch behind your thigh. Hold the position and breathe steadily. Ease back out and switch sides.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('seated-tibial-rotation', 'Seated Tibial Internal Rotation', 'activation', ARRAY['knee_extension_back_knee'], 'warning', 'Sit on a chair with your knee bent to 90 degrees and foot flat on the floor. Keeping the thigh still and the heel planted, slowly rotate your foot and shin inward so the toes sweep toward the opposite leg, then hold 5 seconds at the end of the comfortable range. Feel the small effort behind the knee. Return slowly and repeat 10 times per side. The motion is small — quality of control matters far more than range.', 3, 5, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('shoulder-blade-squeeze', 'Shoulder Blade Squeeze', 'activation', ARRAY['anterior_imbalanced_shoulders'], 'warning', 'Sit or stand tall with arms relaxed at your sides. Draw both shoulder blades back and slightly down, as if pinching a pencil between them — without shrugging or arching the lower back. Hold the squeeze for 5 seconds while breathing steadily, then release slowly. Aim for a firm but comfortable effort, about 70 percent of maximum. Repeat 10 times per set; this can be done several times through the day.', 3, 5, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('side-lunge-adductor-stretch', 'Side Lunge Adductor Stretch', 'stretch', ARRAY['genu_varum_valgum_left', 'genu_varum_valgum_right', 'pelvic_obliquity'], 'maintain', 'Stand with feet wide apart, toes pointing forward. Shift your weight to one side, bending that knee while keeping the other leg straight, until you feel a stretch along the inner thigh of the straight leg. Keep the chest up and hips facing forward; place hands on the bent thigh or the floor for balance. Sink only as deep as the bent-side knee stays over the foot. Hold 30 seconds, push back to center, and repeat on the other side.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('side-lying-hip-abduction', 'Side-Lying Hip Abduction', 'strengthen', ARRAY['pelvic_obliquity', 'genu_varum_valgum_left', 'genu_varum_valgum_right'], 'warning', 'Lie on your side with the bottom leg bent for stability and the top leg straight, body in one line. Keeping the toes of the top foot pointing forward (not up), lift the leg toward the ceiling about 30-45 degrees. Pause 3 seconds at the top, then lower slowly without resting the leg between repetitions. Avoid rolling the hips backward or hiking the waist — the work should sit in the side of the hip. Do 10-12 lifts, then switch sides.', 3, 3, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('side-plank-knees', 'Side Plank from Knees', 'strengthen', ARRAY['pelvic_axial_rotation', 'pelvic_obliquity'], 'warning', 'Lie on your side with knees bent to about 90 degrees and your forearm on the floor, elbow under the shoulder. Keeping knees on the ground, lift your hips until the body forms a straight line from head to knees. Stack the shoulders and hips vertically — avoid rolling forward or letting the hips sag. Hold 15-20 seconds while breathing steadily, lower with control, and repeat on the other side.', 3, 20, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('side-plank', 'Side Plank', 'strengthen', ARRAY['pelvic_axial_rotation', 'pelvic_obliquity'], 'warning', 'Lie on your side with legs straight and stacked, forearm on the floor with the elbow directly under the shoulder. Lift your hips until the body forms one straight line from head to feet, and keep the shoulders and hips stacked vertically. Reach the top arm toward the ceiling or rest it on your hip. Do not let the hips drift back or drop toward the floor. Hold 20-30 seconds breathing steadily, then switch sides.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('single-leg-balance', 'Single Leg Balance', 'activation', ARRAY['pelvic_obliquity', 'genu_varum_valgum_left', 'genu_varum_valgum_right'], 'warning', 'Stand on one foot with a slight bend in the knee. Maintain your balance for 30 seconds. Keep your hips level. Progress to eyes closed for added challenge. Repeat on both sides.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('single-leg-glute-bridge', 'Single-Leg Glute Bridge', 'strengthen', ARRAY['trunk_lean', 'pelvic_axial_rotation', 'knee_extension_back_knee'], 'warning', 'Lie on your back with knees bent and feet flat. Extend one leg straight or hold that knee to your chest. Squeeze the glute of the grounded leg and drive the hips up until the body forms a straight line from knee to shoulder, keeping the pelvis level — do not let one side drop or rotate. Hold 3 seconds at the top, then lower with control. Do 8-10 repetitions on one side before switching. Keep the ribs down and avoid arching the lower back.', 3, 3, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('single-leg-rdl', 'Single-Leg Romanian Deadlift', 'strengthen', ARRAY['trunk_lean', 'knee_extension_back_knee', 'pelvic_obliquity'], 'warning', 'Stand on one leg with a soft bend in that knee, the other foot lightly touching the floor behind you. Hinge forward from the hips, letting the back leg extend behind as your torso lowers toward parallel, keeping the spine long and hips level. Reach toward the floor with the opposite hand, pause 3 seconds, then drive through the standing heel and squeeze the glute to return upright. Do 6-8 slow repetitions per leg; hold a light weight to progress.', 3, 3, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('split-squat', 'Split Squat', 'strengthen', ARRAY['genu_varum_valgum_left', 'genu_varum_valgum_right'], 'warning', 'Take a long stride position, one foot forward and one back, back heel lifted. Keeping the torso tall, lower straight down until the front thigh nears parallel and the back knee hovers above the floor. Watch the front knee: it should track over the second toe the entire time, never collapsing inward. Pause 2 seconds at the bottom, then drive up through the front foot. Do 8-10 repetitions per side; hold light weights to progress.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('standing-band-trunk-rotation', 'Standing Band Trunk Rotation', 'strengthen', ARRAY['pelvic_axial_rotation'], 'warning', 'Stand side-on to a band anchored at chest height, feet hip-width apart, holding the band with both hands in front of your chest. Rotate your trunk away from the anchor with control, leading the motion from your ribs rather than pulling with your arms. Pause 2 seconds at the end of the turn, then return slowly to the start. Keep the hips facing forward throughout. Perform 8-12 controlled repetitions, then switch sides.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('standing-calf-raise', 'Standing Calf Raise', 'strengthen', ARRAY['knee_extension_back_knee'], 'warning', 'Stand tall with your feet hip-width apart. Press up onto the balls of both feet, lifting your heels as high as you comfortably can. Pause at the top, then lower your heels slowly and with control. Rest a hand on a wall for balance if you need it. Move smoothly and keep your ankles steady. Perform 12-15 repetitions per set.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('standing-hamstring-curl', 'Standing Hamstring Curl', 'strengthen', ARRAY['knee_extension_back_knee'], 'warning', 'Stand holding a wall or chair for balance. Slowly curl one heel up toward your glutes against gravity. Hold ~5 seconds at the top, then lower with control. Keep your thighs parallel. Perform 10-12 repetitions per set, then switch legs.', 3, 5, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('standing-ql-stretch', 'Standing Side-Bend Stretch', 'stretch', ARRAY['pelvic_obliquity'], 'maintain', 'Stand with feet hip-width apart. Cross one leg behind the other, then reach the arm on that same side overhead and lean your trunk toward the opposite side, keeping both hips level and facing forward. You should feel a stretch along the side of the lower back and waist, from the hip up toward the ribs. Avoid leaning forward or backward. Hold 30 seconds, return upright slowly, and repeat on the other side.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('standing-quad-stretch', 'Standing Quad Stretch', 'stretch', ARRAY['knee_extension_back_knee'], 'maintain', 'Stand tall holding a wall or chair with one hand for balance. Bend the opposite knee and grasp that ankle behind you, drawing the heel toward your glutes. Keep the knees close together and the pelvis tucked slightly under — avoid arching the lower back — until you feel a stretch along the front of the thigh. Keep the standing knee soft rather than locked back. Hold 30 seconds, release slowly, and repeat on the other side.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('standing-tfl-stretch', 'Standing TFL & IT Band Stretch', 'stretch', ARRAY['genu_varum_valgum_left', 'genu_varum_valgum_right'], 'maintain', 'Stand beside a wall with one hand on it for balance. Cross the leg nearest the wall behind the other leg. Keeping both feet grounded, push the hip nearest the wall toward it while leaning your upper body slightly away, until you feel a stretch along the outside of the hip and thigh of the crossed-behind leg. Keep the trunk tall rather than collapsing sideways. Hold 30 seconds, then switch sides and repeat.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('standing-wall-serratus-slide', 'Standing Wall Serratus Slide', 'activation', ARRAY['anterior_imbalanced_shoulders'], 'warning', 'Stand facing a wall with your forearms resting against it, elbows about shoulder height and shoulder-width apart. Press your forearms into the wall and reach tall, letting your upper back round slightly forward to engage the muscles along your ribs. Keeping that gentle press, slide your forearms upward along the wall, then bring them back down with control. Keep your neck relaxed and your ribs down. Perform 8-12 controlled repetitions per set.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('sternocleidomastoid-stretch', 'Sternocleidomastoid Stretch', 'stretch', ARRAY['forward_head_posture'], 'maintain', 'Sit or stand tall and place one hand flat on your collarbone to gently anchor it down. Rotate your head toward the same side as the hand, then tilt it slightly back and away until you feel a light stretch along the front-side of your neck. Keep the movement small and the jaw relaxed — this area needs only gentle tension. Hold 30 seconds, return slowly, and repeat on the other side.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('suboccipital-release', 'Suboccipital Release with Chin Nod', 'stretch', ARRAY['forward_head_posture'], 'maintain', 'Lie on your back and place a rolled towel or soft massage ball at the base of your skull, just where the head meets the neck. Let the weight of your head rest on it. Slowly nod your chin toward your chest in a small "yes" motion, then return. Keep your jaw and shoulders relaxed throughout. Continue the slow nods for 45-60 seconds, breathing steadily, then rest.', 2, 60, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('supine-chin-nod', 'Supine Chin Nod', 'activation', ARRAY['forward_head_posture'], 'warning', 'Lie on your back with knees bent and head resting on the floor (use a thin towel if needed). Without lifting your head, gently nod your chin toward your throat as if saying a subtle "yes". You should feel the small muscles deep in the front of the neck working, not the big surface muscles. Hold the nod 10 seconds while breathing steadily, then relax. Repeat for the full set.', 3, 10, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('supine-crossover-stretch', 'Supine Crossover Stretch', 'stretch', ARRAY['pelvic_obliquity', 'pelvic_axial_rotation'], 'maintain', 'Lie on your back with both legs extended and arms out to the sides. Lift one leg and guide it across your body toward the opposite side, letting the knee bend as the leg lowers toward the floor. Use the opposite hand on the outside of the knee to add a gentle pull until you feel a stretch along the outside of the hip and into the lower back. Keep both shoulders on the floor. Hold 30 seconds, return with control, and repeat on the other side.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('supine-pelvic-tilt', 'Supine Pelvic Tilt', 'activation', ARRAY['trunk_lean'], 'warning', 'Lie on your back with knees bent and feet flat, arms relaxed at your sides. Gently draw your lower abdomen in and tilt the pelvis so the lower back presses lightly into the floor — imagine pulling the front hip bones toward the ribs. Hold 5 seconds while breathing steadily (do not hold your breath), then relax back to the starting position. Keep the glutes mostly relaxed so the abdominals do the work. Repeat 10 times per set.', 3, 5, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('tall-kneeling-anti-rotation-hold', 'Tall-Kneeling Anti-Rotation Hold', 'activation', ARRAY['pelvic_axial_rotation'], 'warning', 'Kneel tall with both knees down and hips stacked over them, holding a band anchored to one side at chest height. Press your hands straight out in front of your chest and resist the sideways pull, keeping your hips and shoulders square to the front. Breathe steadily and stay tall through the spine for the full hold. Hold 15 seconds, then switch to the other side.', 3, 15, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('terminal-knee-extension', 'Band Terminal Knee Extension', 'strengthen', ARRAY['genu_varum_valgum_left', 'genu_varum_valgum_right'], 'warning', 'Anchor a resistance band at knee height and loop it behind one knee, then step back so the band has tension. With the banded foot flat on the floor, allow that knee a slight bend, then straighten it smoothly against the band, finishing tall without snapping it back. Focus on the inner thigh just above the kneecap doing the final part of the work. Pause 3 seconds in the fully straightened position, soften, and repeat 10-12 times before switching legs.', 3, 3, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('thoracic-extension', 'Thoracic Extension on Foam Roller', 'mobility', ARRAY['forward_head_posture'], 'warning', 'Place a foam roller perpendicular to your spine at mid-back. Support your head with your hands. Extend back over the roller gently. Move slowly up and down the thoracic spine. Pause 3 seconds at each position. Perform 8-10 slow extensions per set.', 2, 3, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('wall-angels', 'Wall Angels', 'strengthen', ARRAY['anterior_imbalanced_shoulders', 'posterior_imbalanced_shoulders'], 'maintain', 'Stand with your back flat against a wall, arms bent at 90 degrees in contact with the wall. Slowly slide your arms up and down like making a snow angel, keeping full contact with the wall. Pause 2-3 seconds at the top of each slide. Perform 8-10 slow slides per set.', 3, 3, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('wall-ankle-dorsiflexion-rock', 'Wall Ankle Dorsiflexion Rock', 'mobility', ARRAY['genu_varum_valgum_left', 'genu_varum_valgum_right'], 'maintain', 'Set up half-kneeling or standing facing a wall, with your front foot a few inches away from it. Drive your front knee forward over your toes toward the wall while keeping that heel flat on the floor. Rock back to the start and repeat, feeling the movement open up through your ankle. Count each forward rock as one repetition per side. Switch sides. Perform 8-10 repetitions per side per set.', 2, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('wall-calf-stretch', 'Wall Calf Stretch (Straight Knee)', 'stretch', ARRAY['knee_extension_back_knee', 'trunk_lean'], 'maintain', 'Face a wall and place both hands on it at shoulder height. Step one foot back about a full stride, keeping that heel flat on the floor and the toes pointing straight at the wall. Keep the back knee straight and lean your hips toward the wall until you feel a stretch in the upper calf of the back leg. Avoid letting the back arch or the heel lift. Hold 30 seconds while breathing slowly, then switch legs.', 3, 30, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('wall-push-up-plus', 'Wall Push-Up Plus', 'activation', ARRAY['anterior_imbalanced_shoulders'], 'warning', 'Stand facing a wall with hands flat on it at shoulder height, arms straight, feet a step back. Keeping the elbows straight, push your upper back away from the wall by spreading the shoulder blades apart — this extra push is the "plus". Hold 2 seconds, then let the shoulder blades glide back together with control. Keep the trunk in one line and avoid sagging hips. Perform 10-15 slow repetitions per set.', 3, 2, NULL, NULL, NULL)
INSERT INTO exercises (slug, name, category, primary_deviation_keys, min_zone, instructions, sets, hold_seconds, video_url, poster_url, demo_gif_url) VALUES ('wall-sit', 'Wall Sit', 'strengthen', ARRAY['genu_varum_valgum_left', 'genu_varum_valgum_right'], 'warning', 'Stand with your back against a wall and feet about half a meter out, hip-width apart. Slide down until your knees bend to roughly 45-60 degrees (work toward 90 as strength builds), keeping the whole back in contact with the wall. Check that both kneecaps track in line with the second toe — not caving inward or bowing out. Hold 20-30 seconds while breathing steadily, then push through the heels to slide back up.', 3, 30, NULL, NULL, NULL)
